import { Routes, Route, Navigate, useLocation, useNavigate } from "react-router-dom";
import { useState, useEffect } from "react";
import Header from "./components/Header/Header";
import Footer from "./components/Footer/Footer";
import Login from "./components/Login/Login";
import Register from "./components/Register/Register";
import ProtectedRoute from "./components/Protected/ProtectedRoute";

function App() {
  const location = useLocation();
  const navigate = useNavigate();
  const [user, setUser] = useState(null);
  
  const isAuthPage =
    location.pathname === "/login" || location.pathname === "/register";

  // Load user from localStorage on mount
  useEffect(() => {
    const storedUser = localStorage.getItem('user');
    if (storedUser) {
      try {
        setUser(JSON.parse(storedUser));
      } catch (err) {
        console.error('Failed to parse user data:', err);
        localStorage.removeItem('user');
        localStorage.removeItem('token');
      }
    }
  }, []);

  // Handle login success
  const handleLoginSuccess = (userData) => {
    setUser(userData);
  };

  // Handle logout
  const handleLogout = () => {
    // Clear localStorage
    localStorage.removeItem('user');
    localStorage.removeItem('token');
    
    // Clear user state
    setUser(null);
    
    // Redirect to login page
    navigate('/login');
  };

  return (
    <>
      {!isAuthPage && (
        <Header 
          user={user} 
          role={user?.role || 'guest'}
          onLogout={handleLogout}
        />
      )}

      <Routes>
        <Route 
          path="/login" 
          element={<Login onLoginSuccess={handleLoginSuccess} />} 
        />
        <Route 
          path="/register" 
          element={<Register onRegisterSuccess={handleLoginSuccess} />} 
        />

        {/* HOME - Customer */}
        <Route
          path="/"
          element={
            <ProtectedRoute>
              <div style={{ padding: '50px', textAlign: 'center' }}>
                <h1>Welcome to 36 Hotel</h1>
              </div>
            </ProtectedRoute>
          }
        />

        <Route
          path="/home"
          element={
            <ProtectedRoute>
              <div style={{ padding: '50px', textAlign: 'center' }}>
                <h1>Welcome to 36 Hotel</h1>
              </div>
            </ProtectedRoute>
          }
        />

        {/* My Bookings */}
        <Route
          path="/my-bookings"
          element={
            <ProtectedRoute>
              <div style={{ padding: '50px', textAlign: 'center' }}>
                <h1>My Bookings</h1>
                <p>Your booking list will appear here</p>
              </div>
            </ProtectedRoute>
          }
        />

        {/* Profile */}
        <Route
          path="/profile"
          element={
            <ProtectedRoute>
              <div style={{ padding: '50px', textAlign: 'center' }}>
                <h1>My Profile</h1>
              </div>
            </ProtectedRoute>
          }
        />

        {/* Receptionist Routes */}
        <Route
          path="/receptionist/booking-list"
          element={
            <ProtectedRoute allowedRoles={['receptionist', 'admin']}>
              <div style={{ padding: '50px', textAlign: 'center' }}>
                <h1>Booking List</h1>
                <p>Receptionist - Manage all bookings</p>
              </div>
            </ProtectedRoute>
          }
        />

        <Route
          path="/receptionist/create-booking"
          element={
            <ProtectedRoute allowedRoles={['receptionist', 'admin']}>
              <div style={{ padding: '50px', textAlign: 'center' }}>
                <h1>Create New Booking</h1>
                <p>Receptionist - Create booking form</p>
              </div>
            </ProtectedRoute>
          }
        />

        <Route
          path="/receptionist/rooms"
          element={
            <ProtectedRoute allowedRoles={['receptionist', 'admin']}>
              <div style={{ padding: '50px', textAlign: 'center' }}>
                <h1>Room Management</h1>
                <p>Receptionist - Manage rooms</p>
              </div>
            </ProtectedRoute>
          }
        />

        {/* Admin Routes */}
        <Route
          path="/admin/dashboard"
          element={
            <ProtectedRoute allowedRoles={['admin']}>
              <div style={{ padding: '50px', textAlign: 'center' }}>
                <h1>Admin Dashboard</h1>
                <p>Admin - System overview</p>
              </div>
            </ProtectedRoute>
          }
        />

        {/* Maintenance Routes */}
        <Route
          path="/maintenance/requests"
          element={
            <ProtectedRoute allowedRoles={['maintenance', 'admin']}>
              <div style={{ padding: '50px', textAlign: 'center' }}>
                <h1>Maintenance Requests</h1>
                <p>Maintenance - Handle repair requests</p>
              </div>
            </ProtectedRoute>
          }
        />

        <Route path="*" element={<Navigate to="/login" replace />} />
      </Routes>

      {!isAuthPage && <Footer />}
    </>
  );
}

export default App;
